package net.civeira.phylax.features.access.tenantloginprovider.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class OidcScopesVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property oidc scopes of tenant login provider ")
  void test_oidc_scopes_v_o_builder() {
    Assertions.assertFalse(OidcScopesVO.nullValue().getOidcScopes().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(OidcScopesVO.tryFrom(null).getOidcScopes().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", OidcScopesVO.from("one").getOidcScopes().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> OidcScopesVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", OidcScopesVO.from("one").toString());
  }
}
